assertEquals(List.of(orderA, orderB), result);

// AssertJ: expressive and readable
assertThat(result)
    .hasSize(2)
    .containsExactly(orderA, orderB);          // order matters

// Assert a property across all elements, order-independent
assertThat(result)
    .extracting(Order::id)
    .containsExactlyInAnyOrder("O1", "O2");
