// Custom exception with a field
class PaymentException extends RuntimeException {
    final String code;
    PaymentException(String code, String msg, Throwable cause) {
        super(msg, cause); this.code = code;
    }
    String code() { return code; }
}

@Test
void wrapsAndReportsPaymentFailure() {
    var ex = assertThrows(PaymentException.class,
        () -> service.charge(badCard));

    assertEquals("CARD_DECLINED", ex.code());            // custom field
    assertTrue(ex.getMessage().contains("declined"));    // message
    assertInstanceOf(GatewayTimeout.class, ex.getCause()); // wrapped cause
}
```

