```java
@Test
void discount_helpful() {
    double price = service.priceFor(premium, 100.0);

    // Message LAST in JUnit 5
    assertEquals(90.0, price,
        "premium customer should get 10% off a $100 order");

    // Supplier: only built if the assertion fails
    assertTrue(price < 100.0,
        () -> "expected a discount but price was " + price + " for " + premium);

    // AssertJ equivalent
    // assertThat(price).as("premium 10%% discount").isEqualTo(90.0);
}
```
